403	static void usbpn_disconnect(struct usb_interface *intf)
404	{
405		struct usbpn_dev *pnd = usb_get_intfdata(intf);
406	
407		if (pnd->disconnected)
408			return;
409	
410		pnd->disconnected = 1;
